CREATE TABLE public.journey_milestone_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pipeline_id uuid NOT NULL REFERENCES public.pipelines(id),stage_key text NOT NULL,title text NOT NULL,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(pipeline_id,stage_key) REFERENCES public.pipeline_stages(pipeline_id,key),UNIQUE(pipeline_id,stage_key,title));
REVOKE ALL ON public.journey_milestone_templates FROM anon,authenticated; GRANT SELECT,INSERT,UPDATE,DELETE ON public.journey_milestone_templates TO authenticated; GRANT ALL ON public.journey_milestone_templates TO service_role;
ALTER TABLE public.journey_milestone_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY hiring7_milestone_templates_read ON public.journey_milestone_templates FOR SELECT TO authenticated USING(public.is_hiring_staff(auth.uid()));
CREATE POLICY hiring7_milestone_templates_write ON public.journey_milestone_templates FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER hiring7_template_touch BEFORE UPDATE ON public.journey_milestone_templates FOR EACH ROW EXECUTE FUNCTION public.hiring_touch_updated_at();
CREATE TABLE public.letter_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('offer','promotion')),name text NOT NULL,body text NOT NULL,is_current boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,legal_review_pending boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,version));
REVOKE ALL ON public.letter_templates FROM anon,authenticated; GRANT SELECT ON public.letter_templates TO authenticated; GRANT ALL ON public.letter_templates TO service_role;
ALTER TABLE public.letter_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY hiring7_letters_admin_read ON public.letter_templates FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX hiring7_current_letter ON public.letter_templates(kind) WHERE is_current;
CREATE TABLE public.journey_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),journey_id uuid NOT NULL REFERENCES public.member_journeys(id),body text NOT NULL,visible_to_candidate boolean NOT NULL DEFAULT false,author_id uuid NOT NULL REFERENCES public.profiles(user_id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.journey_notes FROM anon,authenticated; GRANT SELECT,INSERT ON public.journey_notes TO authenticated; GRANT ALL ON public.journey_notes TO service_role;
ALTER TABLE public.journey_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY hiring7_notes_read ON public.journey_notes FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (visible_to_candidate AND public.hiring_owns_journey(journey_id)));
CREATE POLICY hiring7_notes_admin_insert ON public.journey_notes FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND author_id=auth.uid());
ALTER TABLE public.member_journeys ADD COLUMN mentor_name text;
CREATE FUNCTION public.hiring7_copy_milestones() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.stage_key IS DISTINCT FROM OLD.stage_key THEN INSERT INTO public.journey_milestones(journey_id,stage_key,title,sort_order) SELECT NEW.id,t.stage_key,t.title,t.sort_order FROM public.journey_milestone_templates t WHERE t.pipeline_id=NEW.pipeline_id AND t.stage_key=NEW.stage_key AND NOT EXISTS(SELECT 1 FROM public.journey_milestones m WHERE m.journey_id=NEW.id AND m.stage_key=t.stage_key AND m.title=t.title); END IF; RETURN NEW; END $$;
CREATE TRIGGER hiring7_stage_milestones AFTER INSERT OR UPDATE OF stage_key ON public.member_journeys FOR EACH ROW EXECUTE FUNCTION public.hiring7_copy_milestones();
CREATE FUNCTION public.hiring7_stage_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.stage_key IS DISTINCT FROM OLD.stage_key AND NEW.stage_key IN ('paused','ended') AND coalesce(btrim(NEW.end_reason),'')='' THEN RAISE EXCEPTION 'A reason is required for Paused or Ended'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hiring7_negative_reason BEFORE UPDATE OF stage_key ON public.member_journeys FOR EACH ROW EXECUTE FUNCTION public.hiring7_stage_guard();
CREATE FUNCTION public.start_journey(_application_id uuid,_mentor_id uuid,_start_date date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.applications; j public.jobs; s public.pipeline_stages; result uuid; mentor text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; SELECT * INTO a FROM public.applications WHERE id=_application_id FOR UPDATE; IF NOT FOUND OR a.status_key<>'hired' OR a.is_draft THEN RAISE EXCEPTION 'Only a hired application can start a journey'; END IF; SELECT * INTO j FROM public.jobs WHERE id=a.job_id; SELECT * INTO s FROM public.pipeline_stages WHERE pipeline_id=j.journey_pipeline_id ORDER BY sort_order,id LIMIT 1; IF s.id IS NULL THEN RAISE EXCEPTION 'Choose a journey pipeline with stages first'; END IF; IF _mentor_id IS NOT NULL THEN IF NOT public.is_hiring_staff(_mentor_id) THEN RAISE EXCEPTION 'Choose a hiring staff mentor'; END IF; SELECT coalesce(full_name,email) INTO mentor FROM public.profiles WHERE user_id=_mentor_id; END IF; IF _start_date IS NULL THEN RAISE EXCEPTION 'Start date required'; END IF; INSERT INTO public.member_journeys(application_id,candidate_id,job_id,pipeline_id,stage_key,mentor_id,mentor_name,started_at,stage_started_at) VALUES(a.id,a.candidate_id,a.job_id,s.pipeline_id,s.key,_mentor_id,mentor,(_start_date::timestamp AT TIME ZONE 'Asia/Dhaka'),(_start_date::timestamp AT TIME ZONE 'Asia/Dhaka')) RETURNING id INTO result; INSERT INTO public.journey_events(journey_id,to_stage,note,visible_to_candidate,created_by) VALUES(result,s.key,'Welcome to your team journey',true,auth.uid()); RETURN result; END $$;
CREATE FUNCTION public.hiring7_move_journey(_id uuid,_stage text,_note text,_visible boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF _stage IN ('paused','ended') AND coalesce(btrim(_note),'')='' THEN RAISE EXCEPTION 'A reason is required for Paused or Ended'; END IF; IF _stage='paused' THEN UPDATE public.member_journeys SET end_reason=_note WHERE id=_id; END IF; result:=public.change_journey_stage(_id,_stage,_note,_visible); RETURN result; END $$;
CREATE FUNCTION public.hiring7_set_mentor(_id uuid,_mentor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mentor text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF _mentor IS NOT NULL AND NOT public.is_hiring_staff(_mentor) THEN RAISE EXCEPTION 'Choose a hiring staff mentor'; END IF; SELECT coalesce(full_name,email) INTO mentor FROM public.profiles WHERE user_id=_mentor; UPDATE public.member_journeys SET mentor_id=_mentor,mentor_name=mentor WHERE id=_id; END $$;
CREATE FUNCTION public.grant_hiring_role(_email text,_role public.app_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF _role NOT IN ('reviewer','interviewer') THEN RAISE EXCEPTION 'Choose Reviewer or Interviewer'; END IF; SELECT id INTO uid FROM auth.users WHERE lower(email)=lower(btrim(_email)); IF uid IS NULL THEN RAISE EXCEPTION 'This person must sign in once at /me/login first'; END IF; INSERT INTO public.hiring_user_roles(user_id,role) VALUES(uid,_role) ON CONFLICT(user_id,role) DO NOTHING; RETURN uid; END $$;
CREATE FUNCTION public.revoke_hiring_role(_user_id uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='owner') THEN RAISE EXCEPTION 'Owners keep admin automatically and cannot be revoked here'; END IF; IF _role='admin' THEN RAISE EXCEPTION 'Admin roles cannot be removed here'; END IF; DELETE FROM public.hiring_user_roles WHERE user_id=_user_id AND role=_role; END $$;
CREATE FUNCTION public.hiring7_staff_roles() RETURNS TABLE(user_id uuid,email text,full_name text,roles text[],is_owner boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT p.user_id,p.email,p.full_name,array_agg(r.role::text),EXISTS(SELECT 1 FROM public.user_roles u WHERE u.user_id=p.user_id AND u.role='owner') FROM public.profiles p JOIN public.hiring_user_roles r ON r.user_id=p.user_id GROUP BY p.user_id,p.email,p.full_name; END $$;
CREATE FUNCTION public.hiring7_save_letter(_kind text,_name text,_body text,_pending boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; next_version int; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Hiring admin required' USING ERRCODE='42501'; END IF; IF _kind NOT IN ('offer','promotion') OR btrim(_name)='' OR btrim(_body)='' THEN RAISE EXCEPTION 'Name, kind and body required'; END IF; PERFORM pg_advisory_xact_lock(hashtext('hiring-letter-'||_kind)); SELECT coalesce(max(version),0)+1 INTO next_version FROM public.letter_templates WHERE kind=_kind; UPDATE public.letter_templates SET is_current=false WHERE kind=_kind AND is_current; INSERT INTO public.letter_templates(kind,name,body,version,legal_review_pending) VALUES(_kind,_name,_body,next_version,_pending) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.hiring7_stage_delete_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.applications a JOIN public.jobs j ON j.id=a.job_id WHERE j.application_pipeline_id=OLD.pipeline_id AND a.status_key=OLD.key) OR EXISTS(SELECT 1 FROM public.member_journeys WHERE pipeline_id=OLD.pipeline_id AND stage_key=OLD.key) OR EXISTS(SELECT 1 FROM public.journey_milestones m JOIN public.member_journeys j ON j.id=m.journey_id WHERE j.pipeline_id=OLD.pipeline_id AND m.stage_key=OLD.key) OR EXISTS(SELECT 1 FROM public.journey_milestone_templates WHERE pipeline_id=OLD.pipeline_id AND stage_key=OLD.key) THEN RAISE EXCEPTION 'This stage is in use and cannot be deleted; rename its label instead'; END IF; RETURN OLD; END $$;
CREATE TRIGGER hiring7_used_stage BEFORE DELETE ON public.pipeline_stages FOR EACH ROW EXECUTE FUNCTION public.hiring7_stage_delete_guard();
DO $$ DECLARE name text; BEGIN FOREACH name IN ARRAY ARRAY['start_journey(uuid,uuid,date)','hiring7_move_journey(uuid,text,text,boolean)','hiring7_set_mentor(uuid,uuid)','grant_hiring_role(text,public.app_role)','revoke_hiring_role(uuid,public.app_role)','hiring7_staff_roles()','hiring7_save_letter(text,text,text,boolean)'] LOOP EXECUTE 'REVOKE ALL ON FUNCTION public.'||name||' FROM PUBLIC,anon'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||name||' TO authenticated,service_role'; END LOOP; END $$;
INSERT INTO public.journey_milestone_templates(pipeline_id,stage_key,title,sort_order) SELECT p.id,x.stage,x.title,x.ord FROM public.pipelines p CROSS JOIN (VALUES ('onboarding','Get access to team tools',1),('onboarding','Meet your mentor',2),('onboarding','Read the Admakai quality guide',3),('learner','Make 3 practice shots in Seedance',1),('learner','Practise 10 lighting styles',2),('learner','Finish your first in-house project',3),('learner','Pass the mentor review',4),('project','Deliver your first paid client project',1),('project','Deliver 3 client projects with no major revision',2),('project','Keep office hours for a full month',3)) x(stage,title,ord) WHERE p.name='Admakai Internship Program' AND p.kind='journey';
