View your milestones: https://admakai.com/me/journey',true) ON CONFLICT(trigger_key) DO NOTHING;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['journey_milestones','journey_projects','journey_events','journey_notes','member_journeys'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE public.'||quote_ident(t); END IF; END LOOP; END $$;